//! The key registry table: one [`KeySpec`] per develop key.
//!
//! Seeded from `server-rs/scripts/develop_registry/spec.py` by
//! `gen_table_rs.py` in the same folder, and the source of truth since:
//! edit this file by hand, then refresh the review snapshot with
//! `LRG_BLESS=1 cargo test -p lrg-develop --test registry_snapshot`.
//! Re-running the generator overwrites hand edits.
//!
//! Order is registry order (the sections of the registry: global keys by
//! panel, header, correction, mask tool, nested structures); [`KeyId`]s
//! are indices into this slice.
//!
//! [`KeyId`]: super::KeyId

